import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

export type Book = {
  id: string;
  title: string;
  author: string;
  notes: string;
  status: "reading" | "finished";
  addedAt: string;
  finishedAt: string | null;
};

export type NewBook = Pick<Book, "title" | "author" | "notes">;

function booksFile() {
  return process.env.BOOKS_FILE ?? path.join(process.cwd(), "data", "books.json");
}

async function load(): Promise<Book[]> {
  try {
    const raw = await readFile(booksFile(), "utf8");
    return raw.trim() === "" ? [] : (JSON.parse(raw) as Book[]);
  } catch (err) {
    if ((err as NodeJS.ErrnoException).code === "ENOENT") return [];
    throw err;
  }
}

async function save(books: Book[]) {
  const file = booksFile();
  await mkdir(path.dirname(file), { recursive: true });
  // Write to a sibling temp file then rename so a crash mid-write can't
  // leave a truncated books.json behind.
  const tmp = `${file}.${process.pid}.tmp`;
  await writeFile(tmp, JSON.stringify(books, null, 2) + "\n", "utf8");
  await rename(tmp, file);
}

// All mutations go through this chain so two concurrent form submissions
// can't both read the same snapshot and clobber each other's write.
let queue: Promise<unknown> = Promise.resolve();

function update<T>(fn: (books: Book[]) => T | Promise<T>): Promise<T> {
  const run = queue.then(async () => {
    const books = await load();
    const result = await fn(books);
    await save(books);
    return result;
  });
  queue = run.catch(() => {});
  return run;
}

export async function listBooks(): Promise<Book[]> {
  const books = await load();
  return books.sort((a, b) => b.addedAt.localeCompare(a.addedAt));
}

export async function getBook(id: string): Promise<Book | undefined> {
  const books = await load();
  return books.find((b) => b.id === id);
}

export function addBook(input: NewBook): Promise<Book> {
  return update((books) => {
    const book: Book = {
      id: randomUUID(),
      title: input.title.trim(),
      author: input.author.trim(),
      notes: input.notes.trim(),
      status: "reading",
      addedAt: new Date().toISOString(),
      finishedAt: null,
    };
    books.push(book);
    return book;
  });
}

export function finishBook(id: string): Promise<Book | undefined> {
  return update((books) => {
    const book = books.find((b) => b.id === id);
    if (book && book.status !== "finished") {
      book.status = "finished";
      book.finishedAt = new Date().toISOString();
    }
    return book;
  });
}

export function updateNotes(id: string, notes: string): Promise<Book | undefined> {
  return update((books) => {
    const book = books.find((b) => b.id === id);
    if (book) book.notes = notes.trim();
    return book;
  });
}

