"use server";

import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";
import { addBook, finishBook, updateNotes } from "./books";

export type AddBookState = { error?: string };

export async function addBookAction(
  _prev: AddBookState,
  formData: FormData,
): Promise<AddBookState> {
  const title = String(formData.get("title") ?? "").trim();
  const author = String(formData.get("author") ?? "").trim();
  const notes = String(formData.get("notes") ?? "");

  if (!title || !author) {
    return { error: "Title and author are both required." };
  }

  const book = await addBook({ title, author, notes });
  revalidatePath("/");
  redirect(`/books/${book.id}`);
}

export async function finishBookAction(formData: FormData) {
  const id = String(formData.get("id") ?? "");
  if (!id) return;
  await finishBook(id);
  revalidatePath("/");
  revalidatePath(`/books/${id}`);
}

export async function updateNotesAction(formData: FormData) {
  const id = String(formData.get("id") ?? "");
  if (!id) return;
  await updateNotes(id, String(formData.get("notes") ?? ""));
  revalidatePath(`/books/${id}`);
}

