:root {
  --fg: #1f1f1f;
  --muted: #6b6b6b;
  --bg: #fbfaf7;
  --card: #ffffff;
  --border: #e4e1da;
  --accent: #2f5d50;
  --accent-fg: #ffffff;
  --danger: #a33a3a;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: Georgia, "Times New Roman", serif;
  color: var(--fg);
  background: var(--bg);
  line-height: 1.5;
}

a {
  color: var(--accent);
}

.site-header {
  border-bottom: 1px solid var(--border);
  background: var(--card);
}

.site-title {
  display: block;
  max-width: 44rem;
  margin: 0 auto;
  padding: 1rem 1.25rem;
  font-size: 1.25rem;
  font-weight: bold;
  text-decoration: none;
  color: var(--fg);
}

.container {
  max-width: 44rem;
  margin: 0 auto;
  padding: 1.5rem 1.25rem 4rem;
}

h1,
h2 {
  margin: 0 0 0.75rem;
  line-height: 1.2;
}

h2 {
  font-size: 1.1rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

section + section {
  margin-top: 2.5rem;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.5rem;
}

.book-list li {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 0.75rem 1rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 1rem;
}

.book-list .title {
  font-weight: bold;
  text-decoration: none;
  color: var(--fg);
}

.book-list .title:hover {
  text-decoration: underline;
}

.book-list .author,
.muted {
  color: var(--muted);
}

.empty {
  color: var(--muted);
  font-style: italic;
}

form.stack {
  display: grid;
  gap: 0.75rem;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 1rem;
}

label {
  display: grid;
  gap: 0.25rem;
  font-size: 0.9rem;
}

input,
textarea {
  font: inherit;
  padding: 0.5rem 0.6rem;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: #fff;
}

textarea {
  min-height: 6rem;
  resize: vertical;
}

button {
  font: inherit;
  padding: 0.45rem 0.9rem;
  border: 1px solid var(--accent);
  border-radius: 4px;
  background: var(--accent);
  color: var(--accent-fg);
  cursor: pointer;
}

button.secondary {
  background: transparent;
  color: var(--accent);
}

button:disabled {
  opacity: 0.6;
  cursor: default;
}

.error {
  color: var(--danger);
  margin: 0;
}

.book-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  margin-bottom: 1.5rem;
}

.book-header p {
  margin: 0;
}

.badge {
  display: inline-block;
  font-size: 0.8rem;
  padding: 0.1rem 0.5rem;
  border-radius: 999px;
  border: 1px solid var(--border);
  color: var(--muted);
  white-space: nowrap;
}

.badge.finished {
  border-color: var(--accent);
  color: var(--accent);
}

.notes {
  white-space: pre-wrap;
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 1rem;
  margin: 0;
}

details summary {
  cursor: pointer;
  color: var(--accent);
  margin: 0.75rem 0;
}

