import { mkdtemp, readFile, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { addBook, finishBook, getBook, listBooks, updateNotes } from "./books";

let dir: string;

beforeEach(async () => {
  dir = await mkdtemp(path.join(tmpdir(), "books-"));
  process.env.BOOKS_FILE = path.join(dir, "nested", "books.json");
});

afterEach(async () => {
  delete process.env.BOOKS_FILE;
  await rm(dir, { recursive: true, force: true });
});

describe("books store", () => {
  it("returns an empty list when the file does not exist yet", async () => {
    expect(await listBooks()).toEqual([]);
  });

  it("adds a book as currently reading and persists it to disk", async () => {
    const book = await addBook({ title: " Dune ", author: "Frank Herbert", notes: "" });

    expect(book.status).toBe("reading");
    expect(book.title).toBe("Dune");
    expect(book.finishedAt).toBeNull();

    const onDisk = JSON.parse(await readFile(process.env.BOOKS_FILE!, "utf8"));
    expect(onDisk).toHaveLength(1);
    expect(onDisk[0].id).toBe(book.id);
    expect(await getBook(book.id)).toEqual(book);
  });

  it("marks a book finished exactly once", async () => {
    const book = await addBook({ title: "Dune", author: "Frank Herbert", notes: "" });

    const finished = await finishBook(book.id);
    expect(finished?.status).toBe("finished");
    expect(finished?.finishedAt).toBeTruthy();

    const again = await finishBook(book.id);
    expect(again?.finishedAt).toBe(finished?.finishedAt);
  });

  it("updates notes", async () => {
    const book = await addBook({ title: "Dune", author: "Frank Herbert", notes: "" });
    await updateNotes(book.id, "  Spice.  ");
    expect((await getBook(book.id))?.notes).toBe("Spice.");
  });

  it("returns undefined for unknown ids", async () => {
    expect(await getBook("nope")).toBeUndefined();
    expect(await finishBook("nope")).toBeUndefined();
  });

  it("does not lose writes when several books are added at once", async () => {
    await Promise.all(
      Array.from({ length: 10 }, (_, i) =>
        addBook({ title: `Book ${i}`, author: "Someone", notes: "" }),
      ),
    );
    expect(await listBooks()).toHaveLength(10);
  });
});

